476	// strictCircuitObject decodes one committed circuit record's own member map,
477	// demanding a JSON object with exactly the known top-level fields once.
478	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
479		return strictObjectMembers(raw, what, persistCircuitFields)
480	}
481	
482	// strictObjectMembers decodes one committed record's own member map,
483	// demanding a JSON object without repeated keys. A non-nil allowed list
484	// restricts which keys may appear; nil allows any key. It scans only the
485	// record's own level: the envelope scanner already attributes a duplicated
486	// top-level key to this record, and nested values such as the constraint
487	// definition own their (more precise) strict decoders. Keys are compared
488	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
489	// still a duplicate, even when both values are identical.
490	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
491		trimmed := bytes.TrimSpace(raw)
492		if len(trimmed) == 0 || trimmed[0] != '{' {
493			return nil, corruptf("%s must be a JSON object", what)
494		}
495		dec := json.NewDecoder(bytes.NewReader(trimmed))
496		dec.UseNumber()
497		open, err := dec.Token()
498		if err != nil || open != json.Delim('{') {
499			return nil, corruptf("%s must be a JSON object", what)
500		}
501		var allowed map[string]bool
502		if allowedFields != nil {
503			allowed = make(map[string]bool, len(allowedFields))
504			for _, f := range allowedFields {
505				allowed[f] = true
506			}
507		}
508		members := make(map[string]json.RawMessage)
509		for dec.More() {
510			keyTok, err := dec.Token()
511			if err != nil {
512				return nil, corruptf("%s is not valid JSON: %v", what, err)
513			}
514			key, ok := keyTok.(string)
515			if !ok {
516				return nil, corruptf("%s is not valid JSON", what)
517			}
518			if allowed != nil && !allowed[key] {
519				return nil, corruptf("%s has unknown field %q", what, key)
520			}
521			if _, repeated := members[key]; repeated {
522				return nil, corruptf("%s contains duplicate field %q", what, key)
523			}
524			var value json.RawMessage
525			if err := dec.Decode(&value); err != nil {
526				return nil, corruptf("%s is not valid JSON: %v", what, err)
527			}
528			members[key] = value
529		}
530		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
531			return nil, corruptf("%s is not valid JSON", what)
532		}
533		if _, err := dec.Token(); err != io.EOF {
534			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
535		}
536		return members, nil
537	}
