544	type persistJob struct {
545		ID       string `json:"id"`
546		Circuit  string `json:"circuit"`
547		Version  int    `json:"version"`
548		Kind     string `json:"kind"`
549		Attempt  int    `json:"attempt"`
550		Artifact string `json:"artifact,omitempty"`
551		// CompiledHash is the optional binding to the pinned version's compiled
552		// artifact, stored exactly as submitted.
553		CompiledHash string `json:"compiled_hash,omitempty"`
554	}
555	
556	// compiledHashKey is the canonical spelling of a job record's
557	// compiled-artifact binding field.
558	const compiledHashKey = "compiled_hash"
559	
560	// isCompiledHashKey reports whether key is an accepted spelling of the
561	// compiled-artifact binding field: only "compiled_hash" itself and ASCII
562	// letter-case variants such as "COMPILED_HASH" or "CoMpIlEd_HaSh". Keys are
563	// already JSON-unescaped at this point, so an escaped spelling of any of
564	// these forms lands here too. Non-ASCII letters are never folded here.
565	func isCompiledHashKey(key string) bool {
566		if len(key) != len(compiledHashKey) {
567			return false
568		}
569		for i := 0; i < len(key); i++ {
570			c := key[i]
571			if c >= 'A' && c <= 'Z' {
572				c += 'a' - 'A'
573			}
574			if c != compiledHashKey[i] {
575				return false
576			}
577		}
578		return true
579	}
580	
581	// compiledHashLookalike reports a member key encoding/json would match onto
582	// the binding field's struct tag yet which is not an accepted ASCII spelling
583	// (isCompiledHashKey). Struct-tag matching in encoding/json folds with the
584	// Unicode simple case-folding rules (bytes.EqualFold), so a non-ASCII
585	// lookalike — "compiled_haſh" with U+017F long s, whether written directly
586	// or as the JSON escape u017f — silently fills CompiledHash and would let a
587	// damaged binding (null above all) read as unbound, then vanish on the next
588	// commit. Such a key is damage, regardless of its value or of a correctly
589	// spelled sibling key being present. Several aliases are reported in
590	// lexicographic order so the message is stable.
591	func compiledHashLookalike(members map[string]json.RawMessage) string {
592		var aliases []string
593		for key := range members {
594			if isCompiledHashKey(key) {
595				continue
596			}
597			if strings.EqualFold(key, compiledHashKey) {
598				aliases = append(aliases, key)
599			}
600		}
601		if len(aliases) == 0 {
602			return ""
603		}
604		sort.Strings(aliases)
605		return aliases[0]
606	}
