608	// Strict decoding of the compiled-artifact binding on a committed job record.
609	//
610	// compiled_hash is a field whose presence is meaningful: records written
611	// before bindings existed simply omit it, and an explicit "" is the unbound
612	// state. But once the key appears its value must be a JSON string. A null is
613	// not "no binding" — it is damage to a binding the record claims to carry,
614	// and so is a number, boolean, array or object in its place. Reading either
615	// as the zero string would silently turn a bound job into an unbound one
616	// (and the next commit would drop the field entirely), so the read is
617	// refused as data corruption instead. A repeated key — including one
618	// repeated through JSON string escapes, even with identical values — is
619	// likewise refused rather than resolved to its last value. A legal non-empty
620	// string keeps being matched against the pinned version's artifact by
621	// validateEnvelope, exactly as written.
622	//
623	// The field is recognized under any ASCII letter-case spelling, so a record
624	// carrying "COMPILED_HASH" (or any mixed-case form, escaped or not) is the
625	// same binding and follows the same rules: a single such key is read with
626	// the full string validation above, and two spellings of the field on one
627	// record — even with byte-identical values — are a duplicate binding and
628	// corrupt the read rather than being resolved by key order.
629	//
630	// Non-ASCII spellings are not accepted even though encoding/json itself
631	// would fold them onto the field: its struct-tag matching uses Unicode case
632	// folding, under which "compiled_haſh" (U+017F long s, written directly or
633	// as the JSON escape u017f) names CompiledHash just like "compiled_hash".
634	// Such a lookalike is damage to the binding the record claims to carry and
635	// is refused whatever its value — null, a legal hash or an explicit "" —
636	// and even when a correctly spelled "compiled_hash" sits beside it, in
637	// either key order and whether the two values agree. The damaged binding
638	// must never read as an unbound job and disappear on the next commit.
639	//
640	// Only the binding field is judged here; every other field keeps the
641	// ordinary struct decoding.
642	func (j *persistJob) UnmarshalJSON(raw []byte) error {
643		const what = "stored job record"
644		if string(bytes.TrimSpace(raw)) == "null" {
645			return corruptf("%s must be a JSON object, not null", what)
646		}
647		members, err := strictObjectMembers(raw, what, nil)
648		if err != nil {
649			return err
650		}
651		// Name the job in a binding-field failure when its id is legible; the id
652		// itself is decoded for real by the ordinary pass below.
653		where := what
654		if idRaw, ok := members["id"]; ok {
655			if id, idErr := storedRecordShape.string(idRaw, what+` field "id"`); idErr == nil {
656				where = fmt.Sprintf("stored job record %q", id)
657			}
658		}
659		// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
660		// matching would silently read as this field ("compiled_haſh" with long
661		// s, directly written or ſ-escaped), whatever its value and whether
662		// or not a correctly spelled key accompanies it. It must never be ignored
663		// as an unknown member, which would let a damaged binding read unbound.
664		if alias := compiledHashLookalike(members); alias != "" {
665			return corruptf("%s carries the binding field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
666				where, compiledHashKey, alias)
667		}
668		// Every accepted spelling of the binding field counts as the same one
669		// field; the record may carry it at most once, however it is capitalized.
670		var bindingKeys []string
671		for key := range members {
672			if isCompiledHashKey(key) {
673				bindingKeys = append(bindingKeys, key)
674			}
675		}
676		if len(bindingKeys) > 1 {
677			sort.Strings(bindingKeys)
678			quoted := make([]string, len(bindingKeys))
679			for i, k := range bindingKeys {
680				quoted[i] = strconv.Quote(k)
681			}
682			return corruptf("%s carries the binding field %q more than once (as %s)",
683				where, compiledHashKey, strings.Join(quoted, ", "))
684		}
685		compiledHash := ""
686		hasBinding := false
687		if len(bindingKeys) == 1 {
688			hash, err := storedRecordShape.string(members[bindingKeys[0]], where+` field "compiled_hash"`)
689			if err != nil {
690				return err
691			}
692			compiledHash, hasBinding = hash, true
693		}
694		type plainJob persistJob
695		var decoded plainJob
696		if err := json.Unmarshal(raw, &decoded); err != nil {
697			return corruptf("%s is not valid JSON: %v", what, err)
698		}
699		if hasBinding {
700			decoded.CompiledHash = compiledHash
701		}
702		*j = persistJob(decoded)
703		return nil
704	}
