706	// Store is a persistent workbench backed by one local data directory.
707	//
708	// All operations are safe for concurrent use by multiple goroutines and by
709	// several processes pointed at the same directory: an in-process mutex plus a
710	// process-shared flock serialize commits, and every commit is an atomic
711	// temp-file/fsync/rename replacement. Open the directory with Open and call
712	// Close when done.
713	type Store struct {
714		dir  string
715		mu   sync.Mutex
716		lock *os.File
717	
718		data envelope
719	}
720	
721	// Open opens (creating if needed) the workbench data in dir. If the
722	// directory does not exist it is created. Existing committed data is loaded
723	// and fully validated before Open returns; on a corrupt, truncated or
724	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
725	// leaves every file in the directory untouched.
726	func Open(dir string) (*Store, error) {
727		if dir == "" {
728			return nil, invalidf("data directory must not be empty")
729		}
730		if err := os.MkdirAll(dir, 0o755); err != nil {
731			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
732		}
733		lockPath := filepath.Join(dir, dirLockFile)
734		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
735		if err != nil {
736			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
737		}
738		// Serialize against other processes while we read / validate.
739		if err := lockExclusive(lock); err != nil {
740			lock.Close()
741			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
742		}
743	
744		s := &Store{dir: dir, lock: lock}
745		if err := s.loadLocked(); err != nil {
746			unlockLock(lock)
747			lock.Close()
748			return nil, err
749		}
750		// The lock is taken again per operation; holding it for the store's
751		// lifetime would forbid two open handles on one directory.
752		if err := unlockLock(lock); err != nil {
753			lock.Close()
754			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
755		}
756		return s, nil
757	}
758	
759	// Close releases the directory lock. It does not discard committed data.
760	func (s *Store) Close() error {
761		s.mu.Lock()
762		defer s.mu.Unlock()
763		if s.lock == nil {
764			return nil
765		}
766		var first error
767		if err := unlockLock(s.lock); err != nil {
768			first = err
769		}
770		if err := s.lock.Close(); err != nil && first == nil {
771			first = err
772		}
773		s.lock = nil
774		return first
775	}
776	
777	// Dir reports the data directory backing the store.
778	func (s *Store) Dir() string { return s.dir }
779	
780	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
781	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
782	
783	// loadLocked reads and validates the committed file. Caller must hold the
784	// exclusive flock; the in-process mutex is taken by the public Open path.
785	func (s *Store) loadLocked() error {
786		raw, err := os.ReadFile(s.dataPath())
787		if errors.Is(err, os.ErrNotExist) {
788			s.data = envelope{Format: FormatVersion}
789			return nil
790		}
791		if err != nil {
792			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
793		}
794		if len(strings.TrimSpace(string(raw))) == 0 {
795			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
796		}
797	
798		var env envelope
799		if err := json.Unmarshal(raw, &env); err != nil {
800			// Shape failures surfaced by the persisted-definition decoders are
801			// integrity failures, not JSON syntax errors; report their detail
802			// instead of the generic "not valid JSON" wording.
803			var se StoreError
804			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
805				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
806			}
807			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
808		}
809		if env.Format == 0 {
810			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
811		}
812		if env.Format != FormatVersion {
813			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
814				s.dataPath(), env.Format, FormatVersion)
815		}
816		if err := validateEnvelope(env); err != nil {
817			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
818		}
819		s.data = env
820		return nil
821	}
822	
823	// commitLocked writes the pending state atomically: temp file → fsync →
824	// rename → fsync directory. Caller must hold both the in-process mutex and
825	// the exclusive flock; all in-memory mutations must already have happened and
826	// been rule-checked, so a failure here occurs before any success is reported.
827	func (s *Store) commitLocked() error {
828		s.data.Format = FormatVersion
829		// Stable output: records are stored sorted so files are deterministic.
830		sortEnvelope(&s.data)
831	
832		payload, err := json.MarshalIndent(&s.data, "", "  ")
833		if err != nil {
834			return fmt.Errorf("cannot encode data: %w", err)
835		}
836		payload = append(payload, '\n')
837	
838		tmp := s.tmpPath()
839		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
840		if err != nil {
841			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
842		}
843		if _, err := f.Write(payload); err != nil {
844			f.Close()
845			os.Remove(tmp)
846			return fmt.Errorf("cannot write staged data: %w", err)
847		}
848		if err := f.Sync(); err != nil {
849			f.Close()
850			os.Remove(tmp)
851			return fmt.Errorf("cannot flush staged data: %w", err)
852		}
853		if err := f.Close(); err != nil {
854			os.Remove(tmp)
855			return fmt.Errorf("cannot finish staged data: %w", err)
856		}
857		if err := os.Rename(tmp, s.dataPath()); err != nil {
858			os.Remove(tmp)
859			return fmt.Errorf("cannot commit data file: %w", err)
860		}
861		if err := syncDir(s.dir); err != nil {
862			// The rename already happened; lack of dir fsync only weakens crash
863			// durability, never correctness of what is visible now.
864			return nil
865		}
866		return nil
867	}
868	
869	// withLock runs fn under the in-process mutex and an exclusive flock, then
870	// atomically commits when fn requests it. The on-disk state is re-read after
871	// acquiring the lock, so concurrent commits from another process or another
872	// handle are always observed. Operations validate before mutating; a rejected
873	// operation (commit=false or an error) writes nothing and leaves committed
874	// state unchanged.
875	func (s *Store) withLock(fn func() (commit bool, err error)) error {
876		s.mu.Lock()
877		defer s.mu.Unlock()
878		if s.lock == nil {
879			return invalidf("store is closed")
880		}
881		if err := lockExclusive(s.lock); err != nil {
882			return fmt.Errorf("cannot lock data directory: %w", err)
883		}
884		defer unlockLock(s.lock)
885	
886		if err := s.loadLocked(); err != nil {
887			return err
888		}
889		commit, err := fn()
890		if err != nil {
891			return err
892		}
893		if !commit {
894			return nil
895		}
896		return s.commitLocked()
897	}
898	
899	// withLockRead runs fn under a shared flock over freshly reloaded state.
900	func (s *Store) withLockRead(fn func() error) error {
901		s.mu.Lock()
902		defer s.mu.Unlock()
903		if s.lock == nil {
904			return invalidf("store is closed")
905		}
906		if err := lockShared(s.lock); err != nil {
907			return fmt.Errorf("cannot lock data directory: %w", err)
908		}
909		defer unlockLock(s.lock)
910		if err := s.loadLocked(); err != nil {
911			return err
912		}
913		return fn()
914	}
