916	func sortEnvelope(env *envelope) {
917		sort.Slice(env.Circuits, func(i, j int) bool {
918			if env.Circuits[i].Name != env.Circuits[j].Name {
919				return env.Circuits[i].Name < env.Circuits[j].Name
920			}
921			return env.Circuits[i].Version < env.Circuits[j].Version
922		})
923		sort.Slice(env.Setups, func(i, j int) bool {
924			if env.Setups[i].Name != env.Setups[j].Name {
925				return env.Setups[i].Name < env.Setups[j].Name
926			}
927			return env.Setups[i].Version < env.Setups[j].Version
928		})
929		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
930		sort.Slice(env.Artifacts, func(i, j int) bool {
931			if env.Artifacts[i].Name != env.Artifacts[j].Name {
932				return env.Artifacts[i].Name < env.Artifacts[j].Name
933			}
934			return env.Artifacts[i].Version < env.Artifacts[j].Version
935		})
936	}
937	
938	// validateEnvelope re-checks every invariant on load so a tampered or
939	// hand-edited file cannot bypass the domain rules.
940	func validateEnvelope(env envelope) error {
941		seenCircuit := make(map[[2]string]bool)
942		circuitOK := make(map[[2]string]bool)
943		for i, c := range env.Circuits {
944			key := [2]string{c.Name, itoa(c.Version)}
945			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
946				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
947			}
948			if c.Version <= 0 {
949				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
950			}
951			if seenCircuit[key] {
952				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
953			}
954			seenCircuit[key] = true
955			if c.Constraints <= 0 {
956				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
957			}
958			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
959				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
960			}
961			// The same representability rule the write path enforces: wire 0 plus
962			// every declared input must fit inside the platform's int. A record
963			// beyond that bound can never have been written by this build and
964			// cannot be checked safely, so the directory is corrupt rather than
965			// silently narrowed or read with a wrapped-around layout.
966			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
967				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
968					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
969			}
970			if c.Definition != nil {
971				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
972					return err
973				}
974			}
975			circuitOK[key] = true
976		}
977		seenSetup := make(map[[2]string]bool)
978		for i, p := range env.Setups {
979			key := [2]string{p.Name, itoa(p.Version)}
980			if !circuitOK[key] {
981				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
982			}
983			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
984			if c == nil || !c.Frozen {
985				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
986			}
987			if seenSetup[key] {
988				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
989			}
990			seenSetup[key] = true
991		}
992		seenJob := make(map[string]bool)
993		for i, j := range env.Jobs {
994			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
995				return fmt.Errorf("job #%d has an empty or blank id", i+1)
996			}
997			if seenJob[j.ID] {
998				return fmt.Errorf("job %q appears more than once", j.ID)
999			}
1000			seenJob[j.ID] = true
1001			if j.Kind != "prove" {
1002				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
1003			}
1004			if j.Attempt <= 0 {
1005				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
1006			}
1007			key := [2]string{j.Circuit, itoa(j.Version)}
1008			if !circuitOK[key] {
1009				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
1010			}
1011			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
1012			if c == nil || !c.Frozen {
1013				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
1014			}
1015			if !seenSetup[key] {
1016				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
1017			}
1018			// A recorded compiled-artifact binding must still resolve against the
1019			// pinned version's artifact; a dangling or mismatched binding makes
1020			// the file unreadable rather than silently dropping the binding.
1021			if j.CompiledHash != "" {
1022				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
1023				if artifact == nil {
1024					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
1025				}
1026				if artifact.Hash != j.CompiledHash {
1027					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
1028						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
1029				}
1030			}
1031		}
1032		seenArtifact := make(map[[2]string]bool)
1033		for i, a := range env.Artifacts {
1034			key := [2]string{a.Name, itoa(a.Version)}
1035			if !circuitOK[key] {
1036				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
1037			}
1038			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
1039			if c == nil || !c.Frozen {
1040				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
1041			}
1042			if seenArtifact[key] {
1043				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
1044			}
1045			seenArtifact[key] = true
1046			if c.Definition == nil {
1047				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1048			}
1049			if a.Constraints != c.Constraints {
1050				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1051					a.Name, a.Version, a.Constraints, c.Constraints)
1052			}
1053			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1054			if err != nil {
1055				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1056			}
1057			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1058				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1059			}
1060			wantHash := artifactHash(a.Name, a.Version, def)
1061			if a.Hash != wantHash {
1062				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1063					a.Name, a.Version, a.Hash, wantHash)
1064			}
1065		}
1066		return nil
1067	}
1068	
1069	// validatePersistDefinition re-validates a stored definition against its
1070	// version's declared counts: prime modulus, in-range wires and an exact
1071	// constraint count match.
1072	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1073		parsed, err := definitionFromPersist(*def, public, private)
1074		if err != nil {
1075			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1076		}
1077		if !parsed.compatibleWith(constraints, public, private) {
1078			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1079		}
1080		return nil
1081	}
1082	
1083	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
1084		for i := range cs {
1085			if cs[i].Name == name && cs[i].Version == version {
1086				return &cs[i]
1087			}
1088		}
1089		return nil
1090	}
1091	
1092	func itoa(v int) string { return fmt.Sprintf("%d", v) }
