103	// caseSpellings returns JSON key tokens naming field under non-canonical
104	// case spellings: fully upper, a deterministic mixed case, and the first
105	// letter escaped for both the lower and upper forms.
106	func caseSpellings(field string) map[string]string {
107		upper := strings.ToUpper(field)
108		mixed := make([]byte, len(field))
109		for i := 0; i < len(field); i++ {
110			c := field[i]
111			if i%2 == 0 {
112				c -= 'a' - 'A'
113			}
114			mixed[i] = c
115		}
116		return map[string]string{
117			"upper":         strconv.Quote(upper),
118			"mixed":         strconv.Quote(string(mixed)),
119			"escaped-lower": fmt.Sprintf(`"\u%04x%s"`, field[0], field[1:]),
120			"escaped-upper": fmt.Sprintf(`"\u%04x%s"`, upper[0], upper[1:]),
121		}
122	}
