186	// dupEnvelope builds bytes in which field appears twice: the canonical
187	// member keeps its normal position with firstToken/firstVal, and a second
188	// member with secondToken/secondVal is appended at the end, so the first
189	// spelling always precedes the second in document order.
190	func dupEnvelope(t *testing.T, vals map[string]json.RawMessage, field, firstToken, secondToken string,
191		firstVal, secondVal json.RawMessage) []byte {
192		t.Helper()
193		var kvs []envKv
194		for _, f := range envelopeTopFields {
195			val := vals[f]
196			if len(val) == 0 && f != field {
197				continue // a member the seeded envelope itself omitted (artifacts)
198			}
199			token := strconv.Quote(f)
200			if f == field {
201				token, val = firstToken, firstVal
202			}
203			kvs = append(kvs, envKv{keyToken: token, val: val})
204		}
205		kvs = append(kvs, envKv{keyToken: secondToken, val: secondVal})
206		var buf bytes.Buffer
207		emit := func(kv envKv) {
208			buf.WriteString(kv.keyToken)
209			buf.WriteByte(':')
210			var compact bytes.Buffer
211			if err := json.Compact(&compact, kv.val); err != nil {
212				t.Fatalf("duplicate value is not valid JSON: %v", err)
213			}
214			buf.Write(compact.Bytes())
215		}
216		buf.WriteByte('{')
217		for i, kv := range kvs {
218			if i > 0 {
219				buf.WriteByte(',')
220			}
221			emit(kv)
222		}
223		buf.WriteString("}\n")
224		return buf.Bytes()
225	}
