234	// TestTopLevelFieldCaseVariantDuplicateRefused is the matrix: every one of
235	// the five known fields appearing under two case spellings is rejected,
236	// whichever spelling comes first and even with byte-identical values.
237	func TestTopLevelFieldCaseVariantDuplicateRefused(t *testing.T) {
238		type pair struct {
239			name        string
240			first, last string // JSON key tokens, in document order
241		}
242		pairsFor := func(field string, sp map[string]string) []pair {
243			canonical := strconv.Quote(field)
244			return []pair{
245				{"canonical then upper", canonical, sp["upper"]},
246				{"upper then canonical", sp["upper"], canonical},
247				{"mixed then escaped-lower", sp["mixed"], sp["escaped-lower"]},
248				{"escaped-upper then canonical", sp["escaped-upper"], canonical},
249				{"upper twice", sp["upper"], sp["upper"]},
250			}
251		}
252		for _, field := range envelopeTopFields {
253			spellings := caseSpellings(field)
254			t.Run(field, func(t *testing.T) {
255				for _, tc := range pairsFor(field, spellings) {
256					t.Run(tc.name, func(t *testing.T) {
257						dir, _ := seedBoundStore(t)
258						vals := envelopeValues(readOrderedEnvelope(t, dir))
259						val := vals[field]
260						bad := dupEnvelope(t, vals, field, tc.first, tc.last, val, val)
261						writeRawEnvelope(t, dir, bad)
262						requireTopLevelDupCorrupt(t, dir, bad, field, tc.last)
263					})
264				}
265			})
266		}
267	}
