587				"jobs": `"JOBS"`, "artifacts": `"ARTIFACTS"`,
588			}[key]; ok {
589				kvs[i].keyToken = tok
590			}
591		}
592		writeEnvelope(t, dir, kvs)
593	
594		s, err := Open(dir)
595		if err != nil {
596			t.Fatalf("upper-case envelope rejected: %v", err)
597		}
598		if _, err := s.CreateCircuit(Circuit{Name: "second", Version: 2, Constraints: 1,
599			Description: "d"}); err != nil {
600			t.Fatalf("mutation on upper-case directory: %v", err)
601		}
602		if err := s.Close(); err != nil {
603			t.Fatal(err)
604		}
605	
606		raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
607		if err != nil {
608			t.Fatal(err)
609		}
610		text := string(raw)
611		for _, key := range envelopeTopFields {
612			if !strings.Contains(text, strconv.Quote(key)+":") {
613				t.Fatalf("committed file lost canonical key %q", key)
614			}
615			if strings.Contains(text, strings.ToUpper(strconv.Quote(key))+":") {
616				t.Fatalf("committed file kept upper-case key for %q", key)
617			}
618		}
619		s2, err := Open(dir)
620		if err != nil {
621			t.Fatal(err)
622		}
623		defer s2.Close()
624		if list, err := s2.ListCircuits(); err != nil || len(list) != 2 {
625			t.Fatalf("state lost across canonicalization: %+v %v", list, err)
626		}
627		j, err := s2.GetJob("j1")
628		if err != nil || j.CompiledHash != h {
629			t.Fatalf("binding lost across canonicalization: %+v %v", j, err)
630		}
