cat > /tmp/lookalike_check.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"

	zkc "task029/zkcircuit"
)

func seed(dir string) {
	s, err := zkc.Open(dir)
	if err != nil { panic(err) }
	if _, err := s.CreateCircuit(zkc.Circuit{Name: "mul", Version: 1, Constraints: 1, PublicInputs: 1, PrivateInputs: 1, Description: "d"}); err != nil {
		panic(err)
	}
	if err := s.Close(); err != nil { panic(err) }
}

func try(dir, label string) {
	before, _ := os.ReadFile(filepath.Join(dir, "data.json"))
	s, err := zkc.Open(dir)
	if err == nil {
		list, _ := s.ListCircuits()
		fmt.Printf("%s: OPENED (circuits=%d) -- BAD\n", label, len(list))
		s.Close()
		return
	}
	fmt.Printf("%s: refused: corrupt=%v\n  err: %v\n", label, errors.Is(err, zkc.ErrDataCorrupt), err)
	after, _ := os.ReadFile(filepath.Join(dir, "data.json"))
	fmt.Printf("  file unchanged: %v\n", string(before) == string(after))
}

func inject(dir, member string, before bool) {
	raw, _ := os.ReadFile(filepath.Join(dir, "data.json"))
	var out []byte
	// compact naive: data.json is pretty-printed; find outer braces
	s := string(raw)
	i, j := 0, len(s)-1
	for s[i] != '{' { i++ }
	for s[j] != '}' { j-- }
	if before {
		out = []byte(s[:i+1] + member + "," + s[i+1:])
	} else {
		out = []byte(s[:j] + "," + member + s[j:])
	}
	if err := os.WriteFile(filepath.Join(dir, "data.json"), out, 0o644); err != nil { panic(err) }
}

func main() {
	base := os.Args[1]
	cases := []struct {
		label  string
		member string
		before bool
	}{
		{"circuitſ empty after circuits", `"circuitſ":[]`, false},
		{"circuitſ empty before circuits", `"circuitſ":[]`, true},
		{`circuitſ escaped`, `"circuitſ":[]`, false},
		{"circuitſ null alone (no circuits key)", `"circuitſ":null`, false},
		{"setupſ empty", `"setupſ":[]`, false},
		{"jobſ empty", `"jobſ":[]`, false},
		{"artifactſ empty", `"artifactſ":[]`, false},
		{"cİrcuits (U+0130, unknown, must pass)", `"cİrcuits":1`, false},
		{"note (unknown, must pass)", `"note":1`, false},
	}
	for i, tc := range cases {
		dir := filepath.Join(base, fmt.Sprintf("d%d", i))
		seed(dir)
		inject(dir, tc.member, tc.before)
		try(dir, tc.label)
	}
}
EOF
